/** Add durable local text extraction for Office and searchable PDF attachments. */

import { Buffer } from 'node:buffer'
import { createCanvas } from '@napi-rs/canvas'
import type { Context } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import type { FileAttachmentRef } from '@deepseek-ai/dsh-attachment'
import type { PreStepDecision } from '@deepseek-ai/dsh-agent'
import type { UserMessage } from '@deepseek-ai/dsh-llm'
import { credentialRef } from '@deepseek-ai/dsh-credentials'
import { parseOfficeAsync } from 'officeparser'
import { getDocument } from 'pdfjs-dist/legacy/build/pdf.mjs'
import yauzl from 'yauzl'
import type { Entry } from 'yauzl'
import type { ContentBlock, FileBlock } from '@deepseek-ai/dsh-llm'

import type {} from '@deepseek-ai/dsh-agent'
import type {} from '@deepseek-ai/dsh-attachment'
import type {} from '@deepseek-ai/dsh-credentials'
import type {} from '@deepseek-ai/dsh-llm'

const OFFICE_EXTENSIONS = new Set(['docx', 'pptx', 'xlsx', 'odt', 'odp', 'ods'])
const OCR_API_KEY_REF = 'DSH_FILE_OFFICE_OCR_API_KEY'

/** Limits and optional OCR endpoint used while admitting file messages. */
export interface Config {
  /** Maximum attachment bytes parsed in memory. Default: 32 MiB. */
  maxInputBytes?: number
  /** Maximum uncompressed bytes admitted for one Office ZIP archive. Default: 128 MiB. */
  maxUncompressedBytes?: number
  /** Maximum entries admitted for one Office ZIP archive. Default: 4,000. */
  maxZipEntries?: number
  /** Maximum extracted characters included for one attachment. Default: 200,000. */
  maxExtractedChars?: number
  /** Maximum PDF pages inspected for text and OCR. Default: 20. */
  maxPdfPages?: number
  /** Maximum raster pixels allocated for one PDF page. Default: 4,000,000. */
  maxPdfPagePixels?: number
  /** Maximum raster scale for PDF OCR. Default: 2. */
  maxPdfRenderScale?: number
  /** OpenAI-compatible chat-completions endpoint for scanned PDF pages. */
  ocrEndpoint?: string
  /** Vision model accepted by the configured OCR endpoint. */
  ocrModel?: string
}

/** Configuration schema with bounded parser and rendering resources. */
export const Config: z<Config> = z.object({
  maxInputBytes: z.number().step(1).min(1).default(32 * 1024 * 1024),
  maxUncompressedBytes: z.number().step(1).min(1).default(128 * 1024 * 1024),
  maxZipEntries: z.number().step(1).min(1).default(4_000),
  maxExtractedChars: z.number().step(1).min(1).default(200_000),
  maxPdfPages: z.number().step(1).min(1).default(20),
  maxPdfPagePixels: z.number().step(1).min(1).default(4_000_000),
  maxPdfRenderScale: z.number().min(0.1).default(2),
  ocrEndpoint: z.string(),
  ocrModel: z.string(),
})

/** Cordis Loader name. */
export const name = 'file-recognizer-office'
/** Durable bytes and model-visible message admission. */
export const inject = ['attachments']

function suffix(ref: FileAttachmentRef): string {
  const dot = ref.name.lastIndexOf('.')
  return dot < 0 ? '' : ref.name.slice(dot + 1).toLowerCase()
}

function validateConfig(config: Config): void {
  if (config.ocrEndpoint === undefined && config.ocrModel !== undefined) {
    throw new TypeError('ocrModel requires ocrEndpoint')
  }
  if (config.ocrEndpoint !== undefined) {
    const endpoint = new URL(config.ocrEndpoint)
    const localHttp = endpoint.protocol === 'http:'
      && ['localhost', '127.0.0.1', '[::1]'].includes(endpoint.hostname)
    if (endpoint.protocol !== 'https:' && !localHttp) {
      throw new TypeError('ocrEndpoint must use HTTPS (HTTP is allowed only for loopback hosts)')
    }
    if (config.ocrModel === undefined || config.ocrModel.trim() === '') {
      throw new TypeError('ocrEndpoint requires a non-empty ocrModel')
    }
  }
}

function officeArchive(data: Uint8Array, maxEntries: number, maxBytes: number): Promise<boolean> {
  return new Promise((resolve) => {
    yauzl.fromBuffer(Buffer.from(data), { lazyEntries: true }, (error, archive) => {
      if (error !== null || archive === undefined) {
        resolve(false)
        return
      }
      let entries = 0
      let expandedBytes = 0
      let settled = false
      const finish = (accepted: boolean): void => {
        if (settled) return
        settled = true
        archive.close()
        resolve(accepted)
      }
      archive.on('error', () => { finish(false) })
      archive.on('entry', (entry: Entry) => {
        entries += 1
        expandedBytes += entry.uncompressedSize
        const segments = entry.fileName.split('/')
        if (entries > maxEntries || expandedBytes > maxBytes
          || entry.fileName.startsWith('/') || entry.fileName.includes('\\')
          || segments.some(segment => segment === '..' || segment.includes('\0'))
          || (entry.generalPurposeBitFlag & 1) !== 0) {
          finish(false)
          return
        }
        archive.readEntry()
      })
      archive.on('end', () => { finish(true) })
      archive.readEntry()
    })
  })
}

async function readBytes(
  ctx: Context, config: Config, ref: FileAttachmentRef, signal: AbortSignal,
): Promise<Uint8Array | undefined> {
  if (ref.bytes > (config.maxInputBytes ?? 32 * 1024 * 1024)) return undefined
  const chunks: Uint8Array[] = []
  let length = 0
  for await (const chunk of ctx.attachments.readFileStream(ref, signal)) {
    signal.throwIfAborted()
    length += chunk.byteLength
    if (length > (config.maxInputBytes ?? 32 * 1024 * 1024)) return undefined
    chunks.push(chunk)
  }
  return Buffer.concat(chunks.map(chunk => Buffer.from(chunk)), length)
}

function pageText(items: readonly unknown[]): string {
  return items.flatMap((item) => {
    if (typeof item !== 'object' || item === null || !('str' in item) || typeof item.str !== 'string') return []
    return [item.str]
  }).join(' ').trim()
}

function responseText(payload: unknown): string | undefined {
  if (typeof payload !== 'object' || payload === null || !('choices' in payload) || !Array.isArray(payload.choices)) return undefined
  const first: unknown = payload.choices[0]
  if (typeof first !== 'object' || first === null || !('message' in first)) return undefined
  const message: unknown = first.message
  if (typeof message !== 'object' || message === null || !('content' in message)) return undefined
  const content: unknown = message.content
  if (typeof content === 'string') return content.trim() || undefined
  if (!Array.isArray(content)) return undefined
  const text = content.flatMap((part) => {
    if (typeof part !== 'object' || part === null || !('text' in part) || typeof part.text !== 'string') return []
    return [part.text]
  }).join('\n').trim()
  return text || undefined
}

async function recognizePage(
  ctx: Context, config: Config, data: Uint8Array, pageNumber: number, signal: AbortSignal,
): Promise<string | undefined> {
  const endpoint = config.ocrEndpoint
  const model = config.ocrModel
  if (endpoint === undefined || model === undefined) return undefined
  const credentials = ctx.get('credentials')
  if (credentials === undefined) throw new Error('OCR requires the credentials service')
  const credential = await credentials.resolve(credentialRef(OCR_API_KEY_REF))
  if (credential === undefined) throw new Error(`OCR credential ${OCR_API_KEY_REF} is not configured`)
  const content = [
    { type: 'text', text: `Extract all visible text from PDF page ${pageNumber}. Preserve reading order and do not summarize.` },
    { type: 'image_url', image_url: { url: `data:image/png;base64,${Buffer.from(data).toString('base64')}` } },
  ]
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      authorization: `Bearer ${credential.value}`,
    },
    body: JSON.stringify({ model, messages: [{ role: 'user', content }] }),
    signal,
  })
  if (!response.ok) throw new Error(`OCR endpoint returned HTTP ${response.status}`)
  return responseText(await response.json())
}

async function extractPdf(
  ctx: Context, config: Config, data: Uint8Array, ref: FileAttachmentRef, signal: AbortSignal,
): Promise<string | undefined> {
  const task = getDocument({ data: Uint8Array.from(data) })
  try {
    const document = await task.promise
    const pages: string[] = []
    const limit = Math.min(document.numPages, config.maxPdfPages ?? 20)
    let scannedPages = 0
    for (let pageNumber = 1; pageNumber <= limit; pageNumber += 1) {
      signal.throwIfAborted()
      const page = await document.getPage(pageNumber)
      const extracted = pageText((await page.getTextContent()).items)
      if (extracted.length >= 20) {
        pages.push(`[PDF page ${pageNumber}]\n${extracted}`)
        continue
      }
      if (config.ocrEndpoint === undefined) continue
      scannedPages += 1
      const original = page.getViewport({ scale: 1 })
      const pixels = config.maxPdfPagePixels ?? 4_000_000
      const scale = Math.min(config.maxPdfRenderScale ?? 2, Math.sqrt(pixels / (original.width * original.height)))
      const viewport = page.getViewport({ scale })
      const canvas = createCanvas(Math.ceil(viewport.width), Math.ceil(viewport.height))
      try {
        const canvasContext = Object.assign(canvas.getContext('2d'), { drawFocusIfNeeded: () => {} })
        await page.render({
          canvas: null,
          // NAPI's Canvas API is browser-compatible here but its `canvas` type is not DOM's HTMLCanvasElement.
          canvasContext: canvasContext as unknown as CanvasRenderingContext2D,
          viewport,
        }).promise
        const png = canvas.toBuffer('image/png')
        const text = await recognizePage(ctx, config, png, pageNumber, signal)
        if (text !== undefined) pages.push(`[PDF page ${pageNumber}]\n${text}`)
      } finally {
        canvas.width = 0
        canvas.height = 0
      }
    }
    if (scannedPages > 0 && document.numPages > limit) pages.push(`[PDF OCR limited to the first ${limit} pages of ${document.numPages}.]`)
    if (pages.length === 0) return undefined
    return `[Extracted from ${ref.name}]\n${pages.join('\n\n')}`
  } finally {
    await task.destroy()
  }
}

function bounded(text: string, limit: number): string {
  const normalized = text.trim()
  return normalized.length <= limit ? normalized : `${normalized.slice(0, limit)}\n[Extracted text truncated.]`
}

async function extract(
  ctx: Context, config: Config, ref: FileAttachmentRef, signal: AbortSignal,
): Promise<string | undefined> {
  const extension = suffix(ref)
  if (!OFFICE_EXTENSIONS.has(extension) && extension !== 'pdf') return undefined
  const data = await readBytes(ctx, config, ref, signal)
  if (data === undefined) return undefined
  if (extension === 'pdf') return extractPdf(ctx, config, data, ref, signal)
  if (!await officeArchive(data, config.maxZipEntries ?? 4_000,
    config.maxUncompressedBytes ?? 128 * 1024 * 1024)) return undefined
  const text = (await parseOfficeAsync(Buffer.from(data), { outputErrorToConsole: false })).trim()
  return text === '' ? undefined : `[Extracted from ${ref.name}]\n${text}`
}

function hasFile(block: ContentBlock): block is FileBlock {
  return block.type === 'file'
}

async function extractMessage(ctx: Context, config: Config, message: UserMessage, signal: AbortSignal): Promise<UserMessage> {
  const appended: ContentBlock[] = []
  for (const block of message.content) {
    if (!hasFile(block)) continue
    try {
      const text = await extract(ctx, config, block.attachment, signal)
      if (text !== undefined) {
        appended.push({ type: 'text', text: bounded(text, config.maxExtractedChars ?? 200_000) })
      }
    } catch (error) {
      signal.throwIfAborted()
      ctx.logger.warn(`file-recognizer-office: extraction failed for ${block.attachment.name}`)
      ctx.logger.warn(error)
    }
  }
  return appended.length === 0 ? message : { ...message, content: [...message.content, ...appended] }
}

/** Add parsed attachment text to the same durable user message that holds each file reference. */
export function apply(ctx: Context, config: Config): void {
  validateConfig(config)
  if (config.ocrEndpoint !== undefined && ctx.get('credentials') === undefined) {
    throw new TypeError('OCR requires the credentials service')
  }
  ctx.on('agent/pre-step', async (_payload, next): Promise<PreStepDecision> => {
    const decision = await next()
    if (decision.kind === 'reject') return decision
    const messages: UserMessage[] = []
    for (const message of decision.messages) messages.push(await extractMessage(ctx, config, message, _payload.signal))
    return { ...decision, messages }
  })
}
